-- The data pack contract: field docs, ns.EmptyDB, and ns.DB (the pack if present and compatible, else ns.EmptyDB).
local ADDON_NAME, ns = ...
local L = ns.L

-- The private addon Signpost_Data (generated by tools/, never in this repo) defines the global
-- `Signpost_Data` with the tables below. Signpost must run without it: guides carry their own IDs and coordinates, so
-- every consumer reads ns.DB and treats every table and field as possibly absent. The pack holds only what the route
-- needs (names, positions, links between entities): quest text and progress come from the quest log, item stats and
-- prices from the client. Field names are short because the generated files are large.
-- A coordinate is { uiMapID, x, y } with x/y in percent of that map. `side` is a faction token as returned by
-- UnitFactionGroup, or "both". A race mask has bit 2^(raceID - 1) per race, a class mask 2^(classID - 1) per class.
-- `src` on every record names the layers it came from, comma-separated (client, questie, wowhead, learned: merged in
-- that order, a later layer wins field by field).
--
-- quests[questID]   = { n = name, l = questLevel, r = requiredLevel, side = side,
--                       maxLevel = level,                            -- not offered above it
--                       races = mask, classes = mask,                -- when the quest is limited to them
--                       zone = uiMapID or sort = questSortID,        -- the quest log's header: its zone (for instance
--                                                                    -- quests the instance's uiMapID) or its sort
--                                                                    -- (class, profession, seasonal, ...)
--                       s = { npc = { ids }, obj = { ids }, item = { ids } },   -- who or what starts it
--                       e = { npc = { ids }, obj = { ids } },                   -- who or what ends it
--                       o = { { k = "kill" | "object" | "item" | "spell", id = id,
--                               credit = { npcIDs }, item = itemID },           -- kill credit; the spell's item
--                             { k = "explore", p = { coordinate, ... } }, ... }, -- references only, not log order
--                       preGroup = { questIDs },                     -- all of them must be done first
--                       preSingle = { questIDs },                    -- one of them must be done first
--                       next = questID,                              -- the chain's next quest (once it is taken,
--                                                                    -- this one is no longer offered)
--                       parent = questID,                            -- must be in the log for this one to be offered
--                       exclusive = { questIDs },                    -- doing one of them closes this one
--                       breadcrumbFor = questID,                     -- an optional lead-in to that quest
--                       skill = { skillLineID, rank },               -- a profession requirement (rank 0: any)
--                       repeatable = true,
--                       gives = itemID,                              -- what the giver hands over (a letter, a tool)
--                       needs = { itemIDs } }                        -- needed, though no objective names them
-- npcs[npcID]       = { n = name, side = side or "none",             -- "both" also for neutral creatures; "none":
--                                                                    -- hostile to both factions
--                       p = { coordinate, ... },                     -- up to 3 per map, the map with most spawns
--                                                                    -- first; absent: only inside instances
--                       rank = 1|2|3,                                -- elite, rare elite, boss (absent: not elite)
--                       sp = n,                                      -- spawn points in all (absent: one); the route
--                                                                    -- simulator's respawn model uses it
--                       flags = bits, sub = title }                  -- service NPCs of the pack's faction: vendor 4,
--                                                                    -- flight master 8, trainer 16, innkeeper 128,
--                                                                    -- stable master 8192, repair 16384
-- objects[objectID] = { n = name, p = { coordinate, ... } }
-- items[itemID]     = { n = name, quest = questID,                   -- the quest it starts
--                       drops = { npcIDs },                          -- creatures it drops from
--                       objDrops = { objectIDs },                    -- objects it comes from
--                       vendors = { npcIDs },                        -- who sells it (the pack's faction)
--                       many = count }                               -- it drops from more sources than the export
--                                                                    -- keeps: drops/objDrops then hold only those on
--                                                                    -- the maps of the quests that need it, if any
-- maps[uiMapID]     = { n = name, t = mapType, parent = uiMapID, wowhead = zoneID, flags = n, group = mapGroupID,
--                       lmin = level, lmax = level,             -- the zone's level range (Wowhead), when it has one
--                       world = { instance, x0, y0, x1, y1 },   -- world yards of the map's top-left and bottom-right
--                       rect = { minX, maxX, minY, maxY },      -- the map's rectangle on its parent map (0-1)
--                       taxi = { { id = nodeID, n = name, x = pct, y = pct, faction = 0 | 1 | 2 }, ... },  -- continent
--                       dungeons = { { id = journalInstanceID, n = name, x = pct, y = pct }, ... } }
-- professions[skillLineID] = { n = name, trainers = { npcIDs },
--                       recipes = { [spellID] = { item = itemID, skill = { orange, yellow, green, grey },
--                                   reagents = { [itemID] = count }, src = "trainer" | "vendor" | "drop" | "quest" } },
--                       quests = { questIDs } or { { id, n, l, quests = { questIDs } }, ... } }
--                                                                    -- profession unlock quests: read by the guide
--                                                                    -- lint, not exported yet
-- classes[classFile] = { spells = { [level] = { spellIDs } }, trainers = { npcIDs },  -- classes/<CLASS>.lua
--                       quests = { { id = chainID, n = name, l = level, quests = { questIDs }, new = bool }, ... } }
--                                                                    -- l absent when unknown, new when not checked
-- travel            = { flightMasters = { [npcID] = { node = name, p = coordinate, side = side } },  -- node absent
--                                                                    -- when no client flight node is within 100 yd
--                       transports = { { kind = "boat" | "zeppelin", from = coordinate, to = coordinate,
--                                        side = side, npcs = { npcID, npcID } } },   -- npcs: the two masters
--                       inns = { [npcID] = { p = coordinate, side = side, n = bindLocationName } },
--                       crossings = { { from = coordinate, to = coordinate, name = text, src = ... } } }
-- _meta             = { schema = DATA_SCHEMA, source = "stub" | "generated", generated = "YYYY-MM-DD",
--                       tables = { [name] = { count = n } },
--                       layers = { [layer] = { origin = text, written = "YYYY-MM-DD" } } }

ns.DATA_SCHEMA = 1

ns.EmptyDB = {
	quests = {},
	npcs = {},
	objects = {},
	items = {},
	maps = {},
	professions = {},
	classes = {},
	travel = { flightMasters = {}, transports = {}, inns = {}, crossings = {} },
	_meta = { schema = ns.DATA_SCHEMA, source = "none" },
}

local Data = {}
ns.Data = Data

-- ## OptionalDeps loads Signpost_Data before this file runs (verified on beta 1.60.1.70450); the probe keeps
-- reporting it.
ns.dataPackAtLoad = type(Signpost_Data) == "table"

function Data:Init()
	local pack = Signpost_Data
	ns.DB = ns.EmptyDB
	if type(pack) ~= "table" then
		return
	end
	local meta = type(pack._meta) == "table" and pack._meta or {}
	if meta.schema ~= ns.DATA_SCHEMA then
		self.problem = string.format(
			L["Signpost_Data has schema %s but this version expects %s; running without it."],
			tostring(meta.schema),
			tostring(ns.DATA_SCHEMA)
		)
		return
	end
	-- A view over the pack (never modified) with an empty table for anything this export does not have yet.
	local db = {}
	for key, empty in pairs(ns.EmptyDB) do
		db[key] = pack[key] == nil and empty or pack[key]
	end
	ns.DB = db
end

function Data:Describe()
	if self.problem then
		return self.problem
	end
	if ns.DB == ns.EmptyDB then
		return L["not installed (Signpost runs without it)"]
	end
	local meta = ns.DB._meta
	return string.format(
		L["Signpost_Data %s, source %s, schema %s"],
		tostring(meta.generated or "?"),
		tostring(meta.source or "?"),
		tostring(meta.schema)
	)
end

Data:Init()

ns.Events:Register("PLAYER_LOGIN", function()
	if Data.problem then
		ns.Util.Print(Data.problem)
	end
end)
